sys_security_acl.script:
answer = false;
var lcns = new sn_hr_core.hr_license();
var hasAccess = lcns.hasHrAccess(current.getTableName());
var hasRole  = gs.hasRole('sn_hr_core.case_writer');

if(hasAccess){
	if(new sn_hr_core.hr_Case(current, gs).canEditCase() || new sn_hr_core.hr_Case(current,gs).isApproverUserForCase(gs.getUserID()) || sn_hr_core.hr_Case.userHasSubjectPersonAccess(current))
		answer = true;
}
